import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-02-11","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-02-11","date":"2026-02-11T00:00:00.000Z","updated":"2026-02-19T00:00:00.000Z","tags":["RGW","deduplication","encryption","object storage","server-side encryption"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-11.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-11.md","lastUpdated":1780460162000}'),l={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-11.md"};function o(n,e,h,d,s,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 RGW Refactoring Meeting 主要围绕两个核心议题展开：一是 Gaby 提出的 DDUP（数据去重）与 server-side encryption 结合的设计问题；二是 Matthew 介绍的 AES-256-GCM 加密模式支持 PR。</p><h2 id="议题一-ddup-与-server-side-encryption-的结合" tabindex="-1">议题一：DDUP 与 Server-Side Encryption 的结合 <a class="header-anchor" href="#议题一-ddup-与-server-side-encryption-的结合" aria-label="Permalink to &quot;议题一：DDUP 与 Server-Side Encryption 的结合&quot;">​</a></h2><h3 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;背景与问题&quot;">​</a></h3><p>Gabby 正在实现 DDUP 功能，并希望支持对 server-side encryption 对象进行去重。核心问题有两个：</p><ol><li>是否应该允许加密对象与未加密对象之间进行 DDUP？</li><li>是否可以在已有 E tag（MD5 of clear data）的基础上，额外添加一个更强的 hash（如 SHA 或 BLAKE）用于去重判断？</li></ol><h3 id="加密模式分析" tabindex="-1">加密模式分析 <a class="header-anchor" href="#加密模式分析" aria-label="Permalink to &quot;加密模式分析&quot;">​</a></h3><p>会议讨论了 RGW 支持的几种 server-side encryption 模式：</p><ul><li><strong>SSE-S3（AES-256 模式）</strong>：服务端管理密钥，E tag 为明文数据的 MD5，Amazon 已将此模式设为所有 bucket 的默认行为。</li><li><strong>SSE-KMS</strong>：客户端可指定 KMS key ID，E tag 同样为明文数据的 MD5。</li><li><strong>客户端提供密钥（SSE-C）</strong>：密钥由客户端提供，E tag 为加密数据的 hash，无法直接用于去重。</li></ul><p>关键结论：SSE-S3 和 SSE-KMS 的 E tag 均为明文数据的 MD5，因此服务端可以通过 E tag 判断两个对象是否极有可能相同，这为 DDUP 提供了基础。</p><h3 id="安全性讨论" tabindex="-1">安全性讨论 <a class="header-anchor" href="#安全性讨论" aria-label="Permalink to &quot;安全性讨论&quot;">​</a></h3><p>与会者讨论了 DDUP 是否会引入额外的安全风险：</p><ul><li>SSE-S3 的 E tag 本身就是明文 MD5，任何有 bucket 读权限的用户已经可以通过 E tag 推断两个对象是否相同。</li><li>DDUP 操作本身不会暴露更多信息，因为 E tag 已经提供了等价的信息。</li><li>SSE-S3 的设计目标是保护静态数据（data at rest），防止物理磁盘被盗后数据泄露，而非端到端加密（end-to-end encryption）。</li></ul><h3 id="跨-bucket-ddup-的限制" tabindex="-1">跨 bucket DDUP 的限制 <a class="header-anchor" href="#跨-bucket-ddup-的限制" aria-label="Permalink to &quot;跨 bucket DDUP 的限制&quot;">​</a></h3><p>讨论中发现跨 bucket 进行加密对象 DDUP 存在关键问题：</p><ul><li>SSE-S3 使用 per-bucket key（每个 bucket 独立的加密密钥）。</li><li>如果将 tail object 链接到另一个 bucket 的对象，当原始 bucket 被删除时，对应的加密密钥也会被删除，导致数据无法解密。</li><li>虽然理论上可以通过引用计数（ref count）来 pin 住加密密钥，但这会给非 DDUP 代码路径增加额外开销，不值得。</li></ul><p><strong>结论</strong>：当前阶段，加密对象的 DDUP 只在同一 bucket 内进行，跨 bucket 的加密 DDUP 暂不支持。</p><h3 id="强hash-的必要性" tabindex="-1">强hash 的必要性 <a class="header-anchor" href="#强hash-的必要性" aria-label="Permalink to &quot;强hash 的必要性&quot;">​</a></h3><p>Gabby 提出需要在 E tag（MD5）之外额外存储一个强 hash（SHA 或 BLAKE）：</p><ul><li>MD5 不具备密码学安全性，理论上可以构造碰撞。</li><li>强 hash 可以作为长期属性保留，未来可用于 multi-site sync 优化：在同步时通过比对强 hash 跳过已有数据的传输。</li><li>该 hash 不会暴露给 S3 客户端，仅作为内部属性存储。</li></ul><p>与会者对此基本认可，认为不会带来显著安全风险。</p><h3 id="实现路径" tabindex="-1">实现路径 <a class="header-anchor" href="#实现路径" aria-label="Permalink to &quot;实现路径&quot;">​</a></h3><ul><li>当前优先实现 SSE-S3 模式下同 bucket 内的 DDUP。</li><li>DDUP 依赖 split head 功能完成后才能完整实现（split head 使head object 不再包含嵌入数据）。</li><li>SSE-KMS 模式的 DDUP 支持留待后续，需要进一步确认 E tag 是否为明文 hash。</li><li>跨 bucket 加密 DDUP 的 key pining 方案留待 per-bucket DDUP 验证可行后再评估。</li></ul><h2 id="议题二-aes-256-gcm-加密模式支持" tabindex="-1">议题二：AES-256-GCM 加密模式支持 <a class="header-anchor" href="#议题二-aes-256-gcm-加密模式支持" aria-label="Permalink to &quot;议题二：AES-256-GCM 加密模式支持&quot;">​</a></h2><h3 id="pr-概述" tabindex="-1">PR 概述 <a class="header-anchor" href="#pr-概述" aria-label="Permalink to &quot;PR 概述&quot;">​</a></h3><p>Matthew 介绍了为 RGW server-side encryption 添加 AES-256-GCM 支持的 PR，主要特点：</p><ul><li>GCM 是一种 <strong>size-changing cipher</strong>（认证加密后数据大小会变化），因此需要修复大量假设加密前后数据大小不变的代码，包括 content length计算、offset 追踪等。</li><li>新增三个 head object 属性，用于记录明文大小（plain text size）和原始大小。</li><li>GCM 的核心优势：任何数据损坏或密钥错误都会立即触发 authorization denied，提供完整性保护。</li></ul><h3 id="测试情况" tabindex="-1">测试情况 <a class="header-anchor" href="#测试情况" aria-label="Permalink to &quot;测试情况&quot;">​</a></h3><ul><li>通过了 Teuthology workload 测试。</li><li>通过了 RGW verify suite、crypt suite 和 multi-site suite。</li><li>multi-site suite 中发现一个问题，确认为 main分支已有问题，与本 PR 无关。</li></ul><h3 id="pr-规模与设计" tabindex="-1">PR 规模与设计 <a class="header-anchor" href="#pr-规模与设计" aria-label="Permalink to &quot;PR 规模与设计&quot;">​</a></h3><ul><li>PR 约新增 3600 行代码，主要为单元测试和新的 GCM crypto 类。</li><li>采用通抽象设计，未来添加其他 size-changing cipher（如 ChaCha20）只需新增对应加密类，现有的 size handling、range request 和 multipart 机制均可复用。</li><li>QAT 硬件加速的 stub 已添加，但完整实现尚未完成，不影响代码审查。</li><li>新模式标识为 <code>AES-256-GCM</code>，与现有 <code>AES-256</code>（CBC）模式并列。</li></ul><h3 id="与-ddup-的关系" tabindex="-1">与 DDUP 的关系 <a class="header-anchor" href="#与-ddup-的关系" aria-label="Permalink to &quot;与 DDUP 的关系&quot;">​</a></h3><ul><li>当前 DUP 实现应先聚焦 CBC 模式，GCM 模式的 DDUP 支持留待后续。</li><li>需要 Marcus 和 Matt 进行深度代码审查，建议在 Slack 频道发起 review 请求。</li></ul><h2 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>行动项</th></tr></thead><tbody><tr><td>Gabby</td><td>确认 SSE-KMS 模式下 E tag 是否为明文 MD5</td></tr><tr><td>Gabby</td><td>先实现同 bucket 内 SSE-S3 对象的 DDUP，验证可行性</td></tr><tr><td>Gaby</td><td>与 Marcus 讨论跨 bucket 加密 DDUP 的 key pinning 设计</td></tr><tr><td>Matthew</td><td>在 Slack 频道发起 GCM PR 的 review 请求</td></tr><tr><td>Matthew</td><td>后续完成 QAT 硬件加速支持</td></tr></tbody></table>',35)])])}const b=t(l,[["render",o]]);export{p as __pageData,b as default};
